steps.data:
:root {
  --bg: #0b0b0f;
  --panel: #12121a;
  --panel-2: #161625;
  --text: #e0e0e0;
  --primary: #bb86fc;
  --accent: #9d4edd;
  --border: #2a2a3a;
}

html, body {
  background: var(--bg) !important;
  color: var(--text) !important;
  font-family: Arial, sans-serif;
}

body.wp-admin {
  background: var(--bg) !important;
}

#wpwrap,
#wpcontent,
#wpbody,
#wpbody-content {
  background: var(--bg) !important;
}

#adminmenu,
#adminmenuwrap {
  background-color: #0a0a10 !important;
  border-right: 1px solid var(--border);
}

#adminmenu a {
  color: var(--text) !important;
}

#adminmenu .wp-has-current-submenu a.wp-has-current-submenu {
  background: var(--panel-2) !important;
  color: var(--primary) !important;
  box-shadow: inset 0 0 10px var(--primary);
}

#wpadminbar {
  background: #0a0a10 !important;
  border-bottom: 1px solid var(--border);
}

.postbox,
.wrap,
.notice,
.wp-block,
.components-panel {
  background: var(--panel) !important;
  border: 1px solid var(--border) !important;
  border-radius: 10px;
}

h1, h2, h3 {
  color: var(--primary) !important;
  text-shadow: 0 0 10px var(--primary);
}

button,
.button,
.wp-element-button,
.wp-block-button__link {
  background: var(--accent) !important;
  color: white !important;
  border-radius: 8px !important;
  border: none !important;
}

button:hover,
.button:hover {
  background: #7b2cbf !important;
  box-shadow: 0 0 12px var(--accent);
}

input,
textarea,
select {
  background: #1a1a1a !important;
  color: white !important;
  border: 1px solid var(--accent) !important;
}

body.login {
  background: var(--bg) !important;
}

.login form {
  background: var(--panel) !important;
  border: 1px solid var(--border);
  box-shadow: 0 0 20px rgba(187,134,252,0.2);
}

::selection {
  background: var(--accent);
  color: white;
}

/* =========================
   REMOVE ALL WHITE AREAS
========================= */

.dashboard-widget-wrap,
.dashboard-widget,
.inside,
.postbox .inside,
.metabox-holder,
.meta-box-sortables,
.activity-block,
.draft-comment,
.comment-item,
.community-events-footer,
.community-events,
.rss-widget,
.welcome-panel,
.widefat,
.striped > tbody > :nth-child(odd),
.plugins tr,
.theme-browser .theme,
.card,
.notice,
.update-nag {
  background: #12121a !important;
  color: #e0e0e0 !important;
  border-color: #2a2a3a !important;
}

.widefat td,
.widefat th {
  background: #12121a !important;
  color: #e0e0e0 !important;
  border-color: #2a2a3a !important;
}

.activity-block {
  background: #12121a !important;
}

#dashboard_quick_press form,
#dashboard_quick_press .drafts {
  background: #12121a !important;
}

.comment-item,
.comment-item p,
.comment-meta,
.dashboard-comment-wrap {
  background: #12121a !important;
  color: #e0e0e0 !important;
}

a {
  color: #bb86fc !important;
}

.description,
.community-events-footer,
.tablenav,
.subsubsub {
  color: #b8b8b8 !important;
}

::placeholder {
  color: #888 !important;
}

.postbox-header,
.handle-order-higher,
.handle-order-lower,
.postbox .hndle {
  background: #0f0f15 !important;
  color: #bb86fc !important;
  border-bottom: 1px solid #2a2a3a !important;
}

.plugins .active td,
.plugins .active th {
  background: #181825 !important;
}

::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: #0b0b0f;
}

::-webkit-scrollbar-thumb {
  background: #9d4edd;
  border-radius: 10px;
}

.postbox {
  box-shadow: 0 0 15px rgba(157, 78, 221, 0.15);
}

.postbox:hover {
  box-shadow: 0 0 20px rgba(187, 134, 252, 0.25);
}
 /* =========================
   FIX WELCOME PANEL
========================= */

.welcome-panel,
.welcome-panel-content,
.welcome-panel .welcome-panel-column,
.welcome-panel .welcome-panel-column-container,
.welcome-panel-header {
  background: #12121a !important;
  color: #e0e0e0 !important;
  border-color: #2a2a3a !important;
}

.welcome-panel {
  border: 1px solid #2a2a3a !important;
  border-radius: 14px !important;
  box-shadow: 0 0 20px rgba(157,78,221,0.15);
}

.welcome-panel h2,
.welcome-panel h3,
.welcome-panel p,
.welcome-panel li,
.welcome-panel a {
  color: #bb86fc !important;
}

.welcome-panel a:hover {
  color: #d0a6ff !important;
  text-shadow: 0 0 8px #bb86fc;
}
